package org.sigf.ui;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.concurrent.Task;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.image.*;import javafx.scene.layout.*;import javafx.stage.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Administrative setup and edit form; file paths are never stored. */
public final class ProfileDialog {
 private ProfileDialog(){}
 public static void open(Window owner,Database db,Security.User user,Runnable finished){PharmacyProfileService service=new PharmacyProfileService(db);Task<Optional<PharmacyProfileService.Profile>> load=new Task<>(){protected Optional<PharmacyProfileService.Profile> call()throws Exception{return service.load();}};load.setOnSucceeded(e->show(owner,service,user,load.getValue(),finished));load.setOnFailed(e->{new Alert(Alert.AlertType.ERROR,"No se pudo cargar la configuración: "+load.getException().getMessage()).showAndWait();finished.run();});start(load);}
 private static void show(Window owner,PharmacyProfileService service,Security.User user,Optional<PharmacyProfileService.Profile> saved,Runnable finished){var old=saved.orElse(new PharmacyProfileService.Profile("","","","","","",null));Dialog<Void> d=new Dialog<>();d.initOwner(owner);d.setTitle(saved.isEmpty()?"Configuración inicial de la farmacia":"Datos de la farmacia");ButtonType saveType=new ButtonType("Guardar",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(saveType,ButtonType.CANCEL);GridPane g=new GridPane();g.setHgap(12);g.setVgap(10);g.setPadding(new Insets(18));TextField name=new TextField(old.name()),legal=new TextField(old.legalName()),ruc=new TextField(old.ruc()),address=new TextField(old.address()),phone=new TextField(old.phone()),email=new TextField(old.email());name.setId("profileName");ruc.setId("profileRuc");TextField[] fields={name,legal,ruc,address,phone,email};String[] labels={"Nombre de farmacia *","Razón social","RUC","Dirección","Teléfono","Correo"};for(int i=0;i<fields.length;i++){fields[i].setPrefColumnCount(30);g.addRow(i,new Label(labels[i]),fields[i]);}ImageView preview=new ImageView();preview.setFitWidth(100);preview.setFitHeight(70);preview.setPreserveRatio(true);byte[][] logo={old.logo()};setPreview(preview,logo[0]);Label logoStatus=new Label(logo[0]==null?"Sin logo":"Logo guardado");Button select=new Button("Elegir logo"),remove=new Button("Quitar logo");select.setOnAction(e->{FileChooser f=new FileChooser();f.setTitle("Seleccionar logo");f.getExtensionFilters().add(new FileChooser.ExtensionFilter("Imágenes PNG o JPEG","*.png","*.jpg","*.jpeg"));File file=f.showOpenDialog(d.getDialogPane().getScene().getWindow());if(file==null)return;try{if(Files.size(file.toPath())>2097152)throw new IllegalArgumentException("El logo no puede superar 2 MB");byte[] bytes=Files.readAllBytes(file.toPath());PharmacyProfileService.validateLogo(bytes);logo[0]=bytes;setPreview(preview,bytes);logoStatus.setText("Logo seleccionado");}catch(Exception ex){new Alert(Alert.AlertType.ERROR,Objects.toString(ex.getMessage(),"No se pudo leer el logo")).showAndWait();}});remove.setOnAction(e->{logo[0]=null;setPreview(preview,null);logoStatus.setText("Sin logo");});g.add(new Label("Logo"),0,6);g.add(new VBox(6,new HBox(8,select,remove),logoStatus,preview),1,6);Label notice=new Label("El nombre es obligatorio. La información fiscal no autoriza la emisión de facturas oficiales.");notice.setWrapText(true);notice.getStyleClass().add("muted");Label status=new Label();status.getStyleClass().add("warning");status.setWrapText(true);VBox content=new VBox(10,notice,g,status);d.getDialogPane().setContent(content);d.getDialogPane().setPrefWidth(610);Button save=(Button)d.getDialogPane().lookupButton(saveType);save.setId("profileSave");save.addEventFilter(javafx.event.ActionEvent.ACTION,event->{event.consume();var p=new PharmacyProfileService.Profile(name.getText(),legal.getText(),ruc.getText(),address.getText(),phone.getText(),email.getText(),logo[0]);save.setDisable(true);status.setText("Guardando…");Task<Void> task=new Task<>(){protected Void call()throws Exception{service.save(user,p);return null;}};task.setOnSucceeded(e->{d.close();});task.setOnFailed(e->{save.setDisable(false);status.setText(Objects.toString(task.getException().getMessage(),"No se pudo guardar"));});start(task);});d.setOnHidden(e->finished.run());d.show();}
 private static void setPreview(ImageView view,byte[] data){view.setImage(data==null?null:new Image(new ByteArrayInputStream(data),100,70,true,true));}
 private static void start(Task<?> t){Thread thread=new Thread(t,"sigf-profile");thread.setDaemon(true);thread.start();}
}
